-- Get all users
local users = tool("list_users", {})

-- Days of the week
local days = {"2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"}

-- For each user, get availability for each day
local all_avail = {}
for _, u in ipairs(users) do
  for _, d in ipairs(days) do
    local avail = tool("get_availability", {user_id = u.id, date = d})
    all_avail[#all_avail + 1] = {user_id = u.id, name = u.name, date = d, busy = avail.busy or {}}
  end
end

return {users = users, availabilities = all_avail}

